// AUTO-GENERATED by chatbot/scripts/build-kb.cjs from gctb_nursing_ad_chat.html. Do not edit by hand.
export const KB_FACTS = [{"id":"emi","k":["emi","loan","instalment","installment","monthly","finance","afford","upfront","one time","one-time","pay later","kist","kisht"],"a":"Yes! You can take a student loan that pays the full fee first, and you repay it in small monthly EMIs. No big one time payment. On the call, the counsellor tells you the exact monthly amount."},{"id":"levels","k":["b1","b2","a1","a2","level","how much german","which level","cefr"],"a":"German hospitals usually want B1 to B2 level. Our course takes you all the way from A1 to B2, so you reach exactly what they need."},{"id":"anm","k":["anm","eligible","eligibility","qualify","can i apply","am i","auxiliary","diploma","gnm or","gnm degree","degree enough","enough","my degree","qualification enough"],"a":"If you have GNM or B.Sc Nursing (or Post Basic B.Sc), you can start. Final year students can begin the classes now too. If you only have ANM, that is usually not enough on its own, but share your details and we will guide you."},{"id":"exp","k":["experience","fresher","fresh","years","working","freshers","without experience","no experience"],"a":"Freshers are very welcome. You do not need years of experience. New and experienced nurses both take this path. You mainly need your nursing degree and B2 German."},{"id":"age","k":["age","old","too old","35","40","30","year old","born","umar"],"a":"There is no strict age limit. Nurses of many ages move to Germany. Younger people pick up the language a bit faster, but it is open for you. The counsellor can guide you for your age."},{"id":"ielts","k":["ielts","english","toefl","pte","language test","english exam","angrezi"],"a":"No IELTS or English test is needed for Germany. The only language that matters here is German, up to B2, and that is exactly what we teach you."},{"id":"recog","k":["recognition","recognised","recognized","anerkennung","license","licence","registration","nursing council","valid","accept my degree","approved"],"a":"Yes. Your Indian nursing degree is accepted in Germany through a process called Anerkennung (recognition). It is done with licensed German partners once your German is ready. We prepare you for it fully."},{"id":"visa","k":["visa","work permit","permit","immigration","embassy","blue card"],"a":"Germany has a dedicated work visa for qualified nurses (and the EU Blue Card for skilled professionals). Once your B2 German and degree recognition (Anerkennung) are ready, we connect you with licensed German recruiters who take the job offer and visa forward. Your counsellor gives you the exact steps."},{"id":"family","k":["family","spouse","husband","wife","kids","children","married","reunification","bring my","parents"],"a":"Yes, you can take your family. Once you are settled there on a work visa, you can bring your husband or wife and your kids. The counsellor will explain the timing and papers."},{"id":"pr","k":["pr","permanent","citizenship","settle","stay permanently","green card","residency","future"],"a":"A nursing job in Germany can lead to long term stay, and later PR and even citizenship, because nurses are always needed there. The counsellor will explain the full path."},{"id":"tax","k":["tax","net","in hand","in-hand","take home","after tax","deduction","gross","hand me"],"a":"The Germany salary is before tax. After tax you still keep a good amount, and your health cover and pension are included. The exact in hand depends on your tax class, and the counsellor can give you a real number."},{"id":"docs","k":["document","documents","paperwork","certificate","transcript","passport","what do i need","marksheet"],"a":"For Germany you will typically need your passport, nursing degree and mark sheets, Indian nursing council registration, your B2 German certificate, and the recognition (Anerkennung) papers, plus a job offer. Nothing is needed right now to start — your counsellor shares the full checklist for your stage."},{"id":"cities","k":["city","cities","where in germany","location","hospital","which state","berlin","munich"],"a":"Indian nurses work across many German cities and hospitals. The city depends on the recruiter and the hospital that hires you, and they try to keep your choice in mind."},{"id":"stay","k":["accommodation","stay","house","room","live","housing","settle in","rehna"],"a":"When you move, the hospital and recruiters usually help you with your first accommodation and settling in. You will not be on your own."},{"id":"male","k":["male","man","men","boy","gender","ladka"],"a":"Yes, male nurses are needed just as much in Germany. The path is exactly the same for you."},{"id":"safe","k":["safe","safety","secure country","women safe","alone","ladki"],"a":"Germany is a very safe and well organised country, with strong rules to protect workers. Many Indian nurses, including women and families, live there happily."},{"id":"process","k":["process","step","steps","how does it work","procedure","pathway","roadmap","how it works","kaise"],"a":"It is simple. First, learn German with us from A1 to B2. Second, get your degree recognised (Anerkennung). Third, we refer you to licensed German recruiters who take you through the job, visa and joining. The counsellor walks you through each step."},{"id":"when","k":["when","how soon","start when","go to germany","timeline to move","by when","kab"],"a":"You can start the German classes right away. The actual move happens once you reach B2 and finish recognition and visa, usually in about a year, depending on your pace."},{"id":"other","k":["usa","us","america","canada","uk","england","australia","ireland","dubai","gulf","saudi","other country","abroad"],"a":"Right now we focus fully on Germany, because it has the biggest nurse shortage, strong pay, and a clear legal path for Indian nurses. If you like, the counsellor can still talk you through it on the call."},{"id":"why","k":["why germany","norcet","plan b","better than","instead of","government job","vacancy","worth it","sarkari"],"a":"NORCET has very few seats and a lot of competition. Germany needs thousands of nurses right now, pays almost 8 to 10 times an Indian nurse salary, and your GNM or B.Sc already makes you eligible. It is a strong backup, sometimes even a better first choice."},{"id":"time","k":["how long","duration","time","months","how many months","take","kitna time"],"a":"It usually takes about 10 to 12 months to go from A1 to B2, depending on how fast you learn. Your counsellor will map a clear timeline for you on the call."},{"id":"salary","k":["salary","earn","pay","income","money","package","how much do nurses","lakh","per month","kitna"],"a":"In Germany, nurses earn around 2 to 2.5 lakh rupees a month (it can change a bit by hospital and city). In India a staff nurse gets about 25,000. Plus you get good benefits and paid leave."},{"id":"german","k":["german","language","speak german","learn german","without german","don't know german","dont know german","bhasha"],"a":"No, you do not need any German right now. We start you from zero (A1) and take you up to B2, which is what German hospitals want. Our teachers guide you at every step."},{"id":"cost","k":["cost","fee","fees","price","charges","how much does it cost","expensive","payment","paisa","kitne"],"a":"Great question! I will let your counsellor walk you through the exact fee on the call — the full breakdown and easy-EMI options, with no hidden charges. We only charge for the language training + interview prep (nothing for the referral), and nothing is needed to get started today."},{"id":"legit","k":["genuine","real","scam","fraud","trust","legit","fake","reliable","cheat","sach","farzi"],"a":"Good question. Testbook Global trains you in German, prepares you fully, and connects you with licensed German recruiters who do the hiring. It is a proper, legal and trusted path, not some agent making false promises. Your counsellor shows you everything on the call."},{"id":"place","k":["placement","do you place","will you place","provide job","give job","give me a job","get a job","get me a job","help me get a job","help with job","find a job","job in germany","arrange job","job dilaoge","naukri dilaoge","do you give job"],"a":"We are the training and preparation experts. We take you to B2 German, get you fully ready, and connect you with licensed German recruiters who hire nurses. We guide and support you through the whole journey, and the recruiters and hospitals do the final hiring."},{"id":"guarantee","k":["job guarantee","guarantee","guaranteed","promise","sure job","100 job","confirm job","pakka job","pakki job","assured job"],"a":"We prepare you so well that you become a strong, ready candidate. The final hiring is done by German recruiters and hospitals, and with the huge nurse shortage there, the demand is very high. Your counsellor will explain the full path clearly on the call."},{"id":"refund","k":["refund","money back","cancel","not selected","if i fail","wapas"],"a":"The counsellor will explain the full fee, EMI and terms clearly before you decide, so there are no hidden charges. For the exact refund rules, please confirm on the call."},{"id":"visaprocess","k":["visa process","visa steps","how to get visa","apply visa","visa procedure","visa kaise","get a visa"],"a":"The visa comes near the end, once you are ready. In short: (1) finish the required language/exam, (2) get your nursing degree recognised, (3) get a job offer from a licensed recruiter/employer, (4) apply for the work visa with your documents. For Germany it is a skilled-worker work visa or EU Blue Card. Your counsellor guides each step."},{"id":"flights","k":["flight","flights","ticket","air ticket","airfare","who pays flight","travel cost","fly","flight cost","plane"],"a":"Flights are booked only after your visa and joining date are confirmed. A one-way India-to-Germany ticket is usually around ₹25,000 to ₹45,000 depending on season and city. Some employers or recruiters support relocation/travel costs — your counsellor tells you what applies to your offer."},{"id":"relocation","k":["relocation","shifting","move cost","settling cost","initial expense","one time cost","extra cost"],"a":"Apart from the language fee, plan for a few one-time costs — flight, visa fee, document translation/apostille, and some initial funds to show. They are modest, and the counsellor gives you a clear list so there are no surprises."},{"id":"insurance","k":["insurance","health insurance","medical cover","health cover","travel insurance","bima"],"a":"In Germany health insurance comes with the job — it is deducted from salary and covers you and often your family, from day one. Before you travel you may just need short-term travel insurance. The counsellor explains what to arrange and when."},{"id":"pcc","k":["police clearance","pcc","police verification","background check","character certificate"],"a":"Yes, most countries ask for a Police Clearance Certificate (PCC) for the visa. It is a simple document from your passport office / local police. Nothing to arrange now — the counsellor tells you exactly when and how."},{"id":"medical","k":["medical test","medical checkup","vaccination","health checkup","fitness certificate","medical fitness","vaccine"],"a":"A basic medical fitness check and standard vaccinations are usually needed before joining. It is routine, and the counsellor gives you the checklist at the right stage."},{"id":"funds","k":["funds","money to show","blocked account","sperrkonto","bank balance","proof of funds","savings needed","show money"],"a":"For Germany you may need to show some funds through a blocked account (Sperrkonto) for the visa — roughly a few lakh rupees that stays yours and you use after you arrive. With a confirmed job offer the requirement is lighter. The counsellor gives you your exact figure."},{"id":"exams_other","k":["nclex","oet","cbt","osce","prometric","dha","haad","moh","ahpra","nmc","nmbi","nnas","which exam"],"a":"Each country has its own exam: UK/Ireland need IELTS/OET + registration (NMC/NMBI), Canada needs IELTS + NNAS + a licensing exam, Australia needs IELTS/OET + AHPRA, the Gulf needs a Prometric exam. Germany needs none of these — just German up to B2. That is a big reason it is the easiest path. 🇩🇪"},{"id":"spousework","k":["spouse work","wife work","husband work","partner job","can my wife work","dependent work","family work"],"a":"Yes — in Germany your spouse can usually work too, once they join you on a family visa. That is a big plus versus many other countries. The counsellor explains the conditions."},{"id":"anerkennung","k":["anerkennung","recognition process","recognise degree","recognize degree","equivalence","gutachten","degree recognition"],"a":"Anerkennung is Germany's process that recognises your Indian nursing degree as equal to a German one. You submit your degree, transcripts and registration to a German authority. If they see small gaps, you close them with a short knowledge test or a brief adaptation period. We prepare you for all of it."},{"id":"kenntnis","k":["kenntnisprufung","kenntnis","knowledge test","adaptation","anpassung","defizit","deficit","bridge course"],"a":"If the authority sees small gaps (a Defizitbescheid), you clear them either with a Kenntnisprüfung (a practical/oral knowledge exam) or an Anpassungslehrgang (a short adaptation period at a hospital). It is very manageable, and we prepare you for it."},{"id":"germanvisatype","k":["which visa germany","visa type germany","blue card","recognition visa","work visa germany","germany work permit"],"a":"For Germany, nurses usually travel on a recognition/skilled-worker work visa and can later hold an EU Blue Card. Once your B2 German, recognition and job offer are ready, the recruiter and employer support the visa. Your counsellor maps the exact type for you."},{"id":"germanhealth","k":["german health insurance","krankenversicherung","health insurance germany","medical germany"],"a":"In Germany health insurance is mandatory and automatic with your job — it comes out of your salary and covers doctor visits, hospital and often your family. You are well protected from day one."},{"id":"pflege","k":["pflegefachkraft","registered nurse germany","nurse title","license germany","nursing license","registration germany"],"a":"After recognition you work as a Pflegefachkraft — a fully registered nurse in Germany, with the same rights and pay as a local nurse. That recognition is the key that unlocks the full salary and the PR path."},{"id":"germansteps","k":["germany process","germany steps","full process germany","roadmap germany","step by step germany","germany plan"],"a":"Germany, step by step: (1) learn German A1→B2 with us (about 10 to 12 months), (2) get your degree recognised (Anerkennung), clearing any small gap with a knowledge test if needed, (3) job offer + work visa via licensed recruiters, (4) fly out and join as a registered nurse (Pflegefachkraft), (5) family can join, and a long-term PR path opens up. We guide every single step."},{"id":"settling","k":["settle in germany","integration","adjust","culture shock","new country","first days","language barrier","lonely"],"a":"You will not be alone. With B2 German you can handle daily life comfortably, and hospitals and recruiters help with your first accommodation and paperwork. A large Indian nurse community is already there, so you land among friends."},{"id":"food","k":["vegetarian","veg food","indian food","food","eat","halal","khana","sabzi","cook","groceries"],"a":"You'll eat just fine! Big German cities have Indian stores and restaurants, veg and halal options are easy to find, and most nurses cook their own Indian food at home too. You won't miss your dal-chawal for long!"},{"id":"weather","k":["weather","cold","winter","climate","snow","temperature","thand","garmi"],"a":"Germany is colder than India, especially in winter (it even snows!) But homes, hospitals and transport are all well-heated and warm clothing is easy to get. Most Indians adjust within a few weeks."},{"id":"culture","k":["racism","racist","treated","behave","indians treated","discrimination","culture","adjust","settle in","homesick","alone there"],"a":"Germany is generally very professional and respectful, and nurses are highly valued there. There's already a large, warm Indian nurse community, so you won't feel alone. Every new place takes a little adjusting, but you'll have your people around you."},{"id":"return","k":["come back","return to india","go back","visit india","come to india","vapas","wapas","visit home"],"a":"Of course you can! You get paid leave every year to visit India, and you're free to return permanently whenever you wish. Many nurses visit home once or twice a year. Nothing ties you down."},{"id":"examfail","k":["fail","what if i fail","not pass","unable to clear","clear exam","fail german","fail b2","retake","nervous about german"],"a":"Please don't worry about that! Our teachers stay with you until you're truly ready, and if needed you can re-attempt the German exam. We never leave you midway — we prepare you properly to pass. You've got this!"},{"id":"format","k":["online","offline","class timing","timings","schedule","live class","recorded","how are classes","class time","batch","evening"],"a":"The German classes are live and interactive (online), with flexible batch timings — including evening batches so you can learn alongside your job or studies. Your counsellor will share the exact schedule that suits you."},{"id":"married","k":["married","marriage","shaadi","husband","wife","married woman","pregnant","kids","children with me"],"a":"Absolutely, married nurses are very welcome! And the lovely part — once you're settled on your work visa, you can bring your husband/wife and children along, and your partner can usually work there too. It's a move for the whole family."},{"id":"gap","k":["gap","career gap","not working","break","housewife","years gap","out of practice","career break"],"a":"A career gap is completely okay! Germany cares about your nursing degree and your German level, not a gap. Many nurses who took a break for family restart exactly this way. Just share your details and we'll guide you."},{"id":"ausbildung","k":["paid training","stipend","earn while learning","get paid during","salary during training","ausbildung","paid while"],"a":"Great question! In Germany your main salary starts once you join as a nurse. In some pathways there's a short paid adaptation period at the hospital too. Your counsellor will tell you exactly what applies to your profile."},{"id":"savings","k":["save","savings","send money","send home","how much can i save","remittance","bachat","save money"],"a":"After rent and basic expenses, nurses in Germany are typically able to save and send a good amount home every month — far more than is possible in India. The exact figure depends on your city and lifestyle; your counsellor can give a realistic estimate."},{"id":"parttime","k":["part time","part-time","side job","extra job","work while studying","study more","higher studies","overtime"],"a":"Once you're working as a nurse there, your focus is your job, but Germany does allow extra/side work within the rules, and you can even pursue higher nursing qualifications later. Lots of room to grow."},{"id":"real","k":["is this real","is this genuine","for real","really true","sach me","sach mein","pakka","is it true","not fake","trust"],"a":"Yes, it's completely genuine. Testbook is a well-known Indian ed-tech company, and Germany really does have a big nurse shortage with proper legal work visas. Your counsellor will show you real cases on the call."}];
export const COUNTRY_FACTS = [{"k":"germany","name":"Germany","text":"Germany: salary ₹2–2.5 lakh/month; exam German B1–B2 — no IELTS needed; cost mainly the German language course + interview prep (easy EMI) — no costly foreign-exam fees, and no IELTS. Recognition & visa fees are modest. Counsellor shares the exact fee; visa Work visa / EU Blue Card (after B2 + recognition); timeline about 1 to 1.5 years"},{"k":"uk","name":"UK","text":"UK: salary ₹2.5–3 lakh/month; exam IELTS/OET + NMC (CBT + OSCE); cost roughly ₹2.5–3.5 lakh in process costs — IELTS/OET (~₹15k), NMC CBT + OSCE (~₹1.3 lakh incl. the OSCE taken in the UK) + IHS health surcharge. Many NHS employers reimburse the OSCE & visa; visa Health & Care Worker visa; timeline about 1 to 1.5 years"},{"k":"ireland","name":"Ireland","text":"Ireland: salary ₹2.5–3 lakh/month; exam IELTS/OET + NMBI registration; cost roughly ₹2.5–3.5 lakh — IELTS/OET, NMBI registration (~€350) plus a possible aptitude test or 6–12 week adaptation, then the visa; visa Employment permit; timeline about 1 to 1.5 years"},{"k":"canada","name":"Canada","text":"Canada: salary ₹2.5–3.5 lakh/month; exam IELTS + NNAS assessment + licensing exam; cost high — NNAS assessment (~₹55k), NCLEX-RN (~₹30k), IELTS, provincial licensing + PR/visa fees. Realistically ₹4–6 lakh and often 2+ years; visa Work permit / PR pathways; timeline often 2+ years"},{"k":"australia","name":"Australia","text":"Australia: salary ₹3–3.5 lakh/month; exam IELTS/OET + AHPRA registration; cost high — AHPRA registration + OBA (NCLEX then OSCE taken in Australia, ~A$4k) + skills assessment. Realistically ₹4–6 lakh; visa Skilled / sponsored visa; timeline often 1.5 to 2+ years"},{"k":"gulf","name":"Gulf (UAE / Saudi)","text":"Gulf (UAE / Saudi): salary ₹1–1.5 lakh/month (tax-free); exam Prometric (DHA / HAAD / MOH); cost low — Prometric + DataFlow together ~₹30–40k; the visa is usually employer-sponsored. Fast, but pay is lower and there's no PR path; visa Employment work permit; timeline a few months"}];
